using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

// --- Configuration -----------------------------------------------------------

var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable.");
    return 1;
}

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("A concise heading for the note")] string heading,
         [Description("The note content to save")] string content) =>
        {
            notebook.Add(heading, content);
            return $"Note saved: \"{heading}\"";
        },
        "save_note",
        "Save a research note for later reference when writing the summary."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieve all notes saved so far."),
};

// --- Chat client with automatic tool calling --------------------------------

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Agent loop --------------------------------------------------------------

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine($"\nResearching: {topic}\n");

var systemPrompt = """
    You are a research agent. Your job is to research the given topic thoroughly
    and produce a well-organized summary.

    Follow this process:
    1. Use `web_search` multiple times with varied queries to gather broad information.
    2. Use `save_note` to record key facts, data points, and source snippets as you go.
    3. Use `get_notes` to review everything you collected.
    4. Write a final, comprehensive summary with sections and key takeaways.

    Be thorough — make at least 3 different searches before summarizing.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research the following topic and provide a summary:\n\n{topic}"),
};

var options = new ChatOptions { Tools = [.. tools] };

Console.WriteLine("Agent is working…\n");

var response = await client.GetResponseAsync(messages, options);

Console.WriteLine("─── Research Summary ───────────────────────────────────────\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n────────────────────────────────────────────────────────────");
Console.WriteLine($"\nNotes collected: {notebook.Count}");
return 0;

// === Supporting types ========================================================

/// <summary>Performs web searches via DuckDuckGo Lite (no API key needed).</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var html = await Http.GetStringAsync(
                $"https://html.duckduckgo.com/html/?q={encoded}");

            var results = ParseResults(html);
            if (results.Count == 0)
                return "No results found.";

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();

        var snippetTag = "result__snippet";
        var titleTag = "result__a";
        var pos = 0;

        while (results.Count < 5)
        {
            var titleStart = html.IndexOf($"class=\"{titleTag}\"", pos, StringComparison.Ordinal);
            if (titleStart < 0) break;

            var title = ExtractTagContent(html, titleStart);

            var snippetStart = html.IndexOf($"class=\"{snippetTag}\"", titleStart, StringComparison.Ordinal);
            var snippet = snippetStart >= 0 ? ExtractTagContent(html, snippetStart) : "";

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(CleanHtml(title), CleanHtml(snippet)));

            pos = Math.Max(titleStart + 1, snippetStart > 0 ? snippetStart + 1 : titleStart + 1);
        }

        return results;
    }

    private static string ExtractTagContent(string html, int attrPos)
    {
        var gt = html.IndexOf('>', attrPos);
        if (gt < 0) return "";
        var closeTag = html.IndexOf('<', gt + 1);
        if (closeTag < 0) return "";
        return html[(gt + 1)..closeTag];
    }

    private static string CleanHtml(string text) =>
        WebUtility.HtmlDecode(text.Trim())
            .Replace("\n", " ")
            .Replace("\r", " ")
            .Replace("  ", " ");

    private record SearchResult(string Title, string Snippet);
}

/// <summary>Simple in-memory notebook for the agent to collect research notes.</summary>
class Notebook
{
    private readonly List<(string Heading, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void Add(string heading, string content) => _notes.Add((heading, content));

    public string GetAll()
    {
        if (_notes.Count == 0) return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[{i + 1}] {n.Heading}\n{n.Content}"));
    }
}

